    # For each repeated non-background color, extend collinear diagonal pairs
    # across the grid, preserving any distinct marker cells.
    colors = {v for row in g for v in row if v != bg}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        for i, (r, c) in enumerate(pts):
            for rr, cc in pts[i+1:]:
                dr, dc = rr-r, cc-c
                if abs(dr) == abs(dc) and dr != 0:
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    # Extend line both ways, stopping at grid bounds or another color.
                    for sign in (-1, 1):
                        x, y = r, c
                        while 0 <= x < h and 0 <= y < w:
                            if g[x][y] not in (bg, color):
                                break
                            g[x][y] = color
                            x += sign*sr
                            y += sign*sc
